package dao;import model.*;import java.sql.*;import java.time.*;import java.util.*;
public class StatisticsDAO5 extends DAO5{public StatisticsDAO5(Connection c){super(c);}public MovieStat5[] movies(LocalDate from,LocalDate to)throws Exception{List<MovieStat5>a=query(MovieStat5.class,"SELECT m.*,COUNT(t.id) SoVeBan,COALESCE(SUM(t.Gia),0) TongDoanhThu FROM tblMovie5 m LEFT JOIN tblScreening5 s ON s.tblMovie5id=m.id LEFT JOIN (SELECT t.* FROM tblTicket5 t JOIN tblOrder5 o ON o.id=t.tblOrder5id WHERE o.TrangThai='DA_THANH_TOAN' AND o.NgayLap>=? AND o.NgayLap<?) t ON t.tblScreening5id=s.id GROUP BY m.id",from,to.plusDays(1));for(MovieStat5 x:a){x.setNgayBatDau(from);x.setNgayKetThuc(to);}return a.toArray(new MovieStat5[0]);}public CustomerStat5[] customers(LocalDate from,LocalDate to)throws Exception{List<CustomerStat5>a=query(CustomerStat5.class,"SELECT m.*,c.MaKhachHang,COUNT(DISTINCT o.id) SoLuongGiaoDich,COALESCE(SUM(t.Gia),0) TongChiTieu FROM tblCustomer5 c JOIN tblMember5 m ON m.id=c.id LEFT JOIN tblOrder5 o ON o.tblCustomer5id=c.id AND o.TrangThai='DA_THANH_TOAN' AND o.NgayLap>=? AND o.NgayLap<? LEFT JOIN tblTicket5 t ON t.tblOrder5id=o.id GROUP BY m.id,c.MaKhachHang",from,to.plusDays(1));for(CustomerStat5 x:a){x.setNgayBatDau(from);x.setNgayKetThuc(to);x.setThe(new MembershipCardDAO5(con).forCustomer(x.getId()));}return a.toArray(new CustomerStat5[0]);}}
